import { memo, useDeferredValue, useState } from "react";

const Results = memo(function Results({ items, query }) {
  return <ul>{items.filter(item => item.name.includes(query))
    .map(item => <li key={item.id}>{item.name}</li>)}</ul>;
});

export default function Search({ items }) {
  const [query, setQuery] = useState("");
  const deferredQuery = useDeferredValue(query);
  return (
    <div>
      <input aria-label="Search" value={query}
        onChange={event => setQuery(event.target.value)} />
      <div style={{ opacity: query !== deferredQuery ? 0.6 : 1 }}>
        <Results items={items} query={deferredQuery} />
      </div>
    </div>
  );
}

